"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5063],{92665:e=>{e.exports=JSON.parse('{"functions":[{"name":"_validate","desc":"Self-check (not run in production \u2014 call from a test or Studio guard).\\nAsserts every authored season has strictly-ascending xpRequired, contiguous\\ntier indices, and challenge weeks within the season\'s week count. Returns\\ntrue on success; errors (via assert) on the first violation.","params":[],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":361,"path":"src/Shared/Data/Season/SeasonData.luau"}}],"properties":[],"types":[],"name":"SeasonData","desc":"Authoritative, shared definition of the Season Pass (battle pass) content:\\nthe tier currency-cost curve, coins-only reward tables, and weekly challenges\\nfor the current and next season. Pure data + helpers \u2014 no Roblox service\\naccess, so it can be required from both the server and the client (and\\nunit-checked).\\n\\nProgression is currency-based: `season.xp` is the season currency the player\\nhas banked (from completing weekly challenges \u2014 see SeasonService), and tier\\nN unlocks once that reaches the tier\'s `xpRequired` cost. The field is still\\nnamed `xp` internally; the mechanic is unchanged (accumulate, cross a\\nthreshold), only its source (challenges only) and values (small costs) moved.\\n\\nv1 scope: rewards are coins only. The `Reward` type is left extensible\\n(`{ kind, amount }`) so item-style reward kinds can slot in later without\\ntouching consumers that already switch on `reward.kind`.\\n\\nNOTE (boilerplate): every season, challenge, and metric below is PLACEHOLDER\\ncontent. Replace the seasons, the challenge metrics (and the game systems\\nthat report them via SeasonService.reportChallenge), and the curve values\\nwith your game\'s real content. The schema and helpers are the product.","source":{"line":28,"path":"src/Shared/Data/Season/SeasonData.luau"}}')}}]);